from tests_src import T, Q2, TF

T(32, "32-8", "Stephen Hawking: Asking the Biggest Questions", "Information Report", [
"Stephen Hawking was born on the 8th of January 1942 in the university city of Oxford, and it was there, at University College, that he studied physics and earned first-class honours. In October 1962 he moved to Cambridge to begin research, which means trying to answer a question that nobody has yet answered, and in 1966 he gained a doctorate there. Cambridge became his base as a scientist, and he remained a fellow of one of its colleges throughout his life.",
"Hawking\u2019s chief interest was the universe as a whole, and in particular the objects known as black holes. A black hole is so dense that the pull of gravity just beneath its surface is strong enough that nothing, not even light, can escape. For that reason, scientists had long assumed that a black hole could only ever take things in. In 1974, however, Hawking worked out that black holes should give off a faint glow of radiation, now known as Hawking radiation. This meant that a black hole slowly loses energy. Over an immense stretch of time, it could even fade away altogether.",
"The idea was so surprising that it changed how physicists thought about black holes. In the same year, Hawking was elected a Fellow of the Royal Society, a long-established society of scientists, and in 1979 he became Lucasian Professor of Mathematics at Cambridge, a position once held by Isaac Newton. In 1982 he was awarded a CBE, an honour given in Britain for outstanding achievement. Among the many other honours he received were the Copley Medal and the Albert Einstein Award.",
"Throughout these years, Hawking\u2019s body grew weaker, and he came to use a wheelchair. Later he lost his own speaking voice, and he communicated through a computer that spoke on his behalf. At first he operated it with a handheld switch and, eventually, with a single cheek muscle. The voice it produced became instantly recognisable across the world. Yet none of this stopped him from working, and he stayed scientifically active for many years.",
"Hawking was not content for his ideas to stay within universities. In 1988 he published A Brief History of Time, a book that explained the universe to ordinary readers rather than to specialists. It became a surprise bestseller, remaining on the Sunday Times best-seller list for a record-breaking 237 weeks, and millions of copies were sold. Further books followed, among them The Universe in a Nutshell in 2001 and, four years later, A Briefer History of Time, which he wrote with Leonard Mlodinow.",
"In 2009 he received the Presidential Medal of Freedom, an honour given by the United States. Prizes, though, tell only part of the story. Hawking\u2019s lasting importance lies in the questions he chose to ask, and in his willingness to share the answers with anyone curious enough to listen.",
], [
 dict(d="2a", k="mc", m=1, q="In paragraph 2, what does the word \u201cimmense\u201d mean in the phrase \u201can immense stretch of time\u201d?", opts=["Quite brief", "Not certain", "Very long", "Commonplace"], a="C"),
 dict(d="2b", k="short", m=1, q="In which year did Stephen Hawking move to Cambridge to begin his research?", a="1962.", g="Accept 1962 (October 1962)."),
 dict(d="2b", k="find", m=1, q="Find and copy the words from paragraph 3 that name the position at Cambridge that was once held by Isaac Newton.", a="Lucasian Professor of Mathematics", g="Accept \u201cLucasian Professor of Mathematics\u201d only. \u201cLucasian Professor\u201d alone is acceptable."),
 dict(d="2b", k="short", m=1, q="Before Hawking\u2019s work in 1974, what had scientists long assumed a black hole could do?", a="It could only take things in.", g="Accept: take things in / nothing could come out or escape from it."),
 dict(d="2d", k="short", m=2, q="Explain why Hawking\u2019s discovery meant that a black hole could eventually fade away.", a="Black holes give off radiation, so they slowly lose energy; over a very long time they could disappear.", g="1 mark for: giving off radiation / losing energy. 1 mark for: over a very long time / gradually. Max 2."),
 dict(d="2c", k="order", m=1, q="Number the events from 1 to 4 to show the order in which they happened.", items=["Hawking became Lucasian Professor of Mathematics.", "Hawking moved to Cambridge to begin research.", "Hawking published A Brief History of Time.", "Hawking worked out that black holes give off radiation."], a=[3, 1, 4, 2], g=Q2),
 dict(d="2b", k="tf", m=1, q="Tick True or False for each sentence.", items=["Hawking studied physics at Oxford before he went to Cambridge.", "Hawking radiation was first described in 1988.", "Hawking always operated his computer with a handheld switch.", "The Universe in a Nutshell was published after A Brief History of Time."], a=["T", "F", "F", "T"], g=TF),
 dict(d="2b", k="short", m=2, q="Give two ways in which Hawking operated the computer that spoke for him.", a="With a handheld switch; with a single cheek muscle.", g="1 mark each. Accept: a switch held in the hand / a small movement of a cheek muscle. Max 2."),
 dict(d="2d", k="short", m=1, q="In paragraph 4, the writer says, \u201cYet none of this stopped him from working.\u201d What does this tell you about Hawking?", a="He kept doing his scientific work in spite of the difficulties he faced (he was determined).", g="Accept any answer showing that he continued to work despite using a wheelchair and computer voice / was determined or hard-working."),
 dict(d="2a", k="mc", m=1, q="In paragraph 3, an honour is described as being given for \u201coutstanding achievement\u201d. What does \u201coutstanding\u201d mean here?", opts=["Very good", "Very recent", "Well known", "Quite usual"], a="A"),
 dict(d="2d", k="short", m=1, q="\u201cHawking was not content for his ideas to stay within universities.\u201d What does this tell you about what he wanted?", a="He wanted ordinary people, not only scientists, to be able to understand his ideas.", g="Accept: he wanted to share his ideas with everyone / with the public / with ordinary readers."),
 dict(d="2g", k="short", m=1, q="The writer ends by saying, \u201cPrizes, though, tell only part of the story.\u201d What does the writer want the reader to understand?", a="That Hawking\u2019s importance is not only about his awards but about the questions he asked and how he shared his answers.", g="Accept any answer that says the awards are not the whole picture / his questions and sharing of ideas matter more."),
 dict(d="2d", k="mc", m=1, q="What does paragraph 4 suggest about Hawking\u2019s computer voice?", opts=["It was chosen by his colleagues.", "It was difficult for people to follow.", "It was replaced when he grew older.", "It was known all over the world."], a="D"),
 dict(d="2c", k="mc", m=1, q="Which sentence best sums up the whole text?", opts=["Hawking wrote a bestselling book that was mostly about Isaac Newton.", "Hawking used a wheelchair and a computer voice to communicate with others.", "Hawking studied black holes and explained his ideas to ordinary readers.", "Hawking won more prizes than any other scientist who has ever lived."], a="C"),
])

T(33, "33-7", "A Letter to Cambridge", "Recount (Historical)", [
"Srinivasa Ramanujan was born on the 22nd of December 1887 in Erode, in southern India, but he grew up in the town of Kumbakonam, where his mother took him when he was one year old. In January 1898 he entered the Town High School there, and it was in that school that he came across a book that would shape the rest of his life.",
"The book was a Synopsis of elementary results in pure mathematics by G. S. Carr, and it was not a gentle textbook for beginners but a compact collection of theorems, formulae and short proofs. Ramanujan used it to teach himself, and he went on to make discoveries of his own, filling notebooks with results that eventually numbered nearly 3,900, a large proportion of them entirely new.",
"Ramanujan had no university education to support his work, and in 1912 he took a post as a clerk at the Madras Port Trust, which provided a steady wage while he continued with mathematics alongside his job. In January 1913 he did something bold: he wrote to G. H. Hardy, a well-known mathematician at Cambridge, enclosing a long list of theorems that he had not proved. In the letter he explained plainly that, although he had no university education, he had completed the ordinary school course.",
"Hardy studied the list together with a colleague, J. E. Littlewood. On the 8th of February 1913, Hardy replied. He explained that the results fell into three groups: some were already known, some were new but merely curious, and some appeared to be both new and important. It was clear that Ramanujan possessed a remarkable gift, and Hardy arranged for him to travel to England.",
"Ramanujan sailed from India on the 17th of March 1914 and arrived in London on the 14th of April. At the end of the month he moved into rooms at Trinity College, Cambridge. There he worked closely with Hardy and Littlewood, and in 1916 he received a degree of Bachelor of Arts by Research.",
"Two further honours followed in 1918. In May, at the age of 31, he was confirmed as a Fellow of the Royal Society, and in October he was elected a Fellow of Trinity College, the first Indian to be given that honour.",
"Hardy later recorded a well-known story about their friendship. He had arrived in a taxi numbered 1729 and remarked that it seemed a rather dull number. Ramanujan disagreed at once. It was, he said, the smallest number that can be written as the sum of two cubes in two different ways, since 1729 is both 1 cubed plus 12 cubed and 9 cubed plus 10 cubed.",
"Ramanujan\u2019s notebooks were not forgotten. Mathematicians have continued to study the theorems they contain, and the pages that a clerk once wrote in southern India still yield ideas today.",
], [
 dict(d="2a", k="mc", m=1, q="In paragraph 2, the book is described as \u201ca compact collection\u201d of theorems. What does \u201ccompact\u201d suggest about the book?", opts=["It was old and worn out.", "It was tightly packed.", "It was written for beginners.", "It was hard to find in shops."], a="B"),
 dict(d="2b", k="short", m=1, q="In which town did Ramanujan grow up?", a="Kumbakonam.", g="Accept Kumbakonam. Do not accept Erode (where he was born)."),
 dict(d="2b", k="find", m=1, q="Find and copy the words from paragraph 3 that tell you what job Ramanujan took in 1912.", a="a clerk at the Madras Port Trust", g="Accept \u201ca clerk at the Madras Port Trust\u201d or \u201cclerk at the Madras Port Trust\u201d."),
 dict(d="2d", k="short", m=2, q="In paragraph 3, the writer says that writing to Hardy was \u201csomething bold\u201d. Why was it bold? Use evidence from the text.", a="He had no university education and he was writing to a well-known Cambridge mathematician, sending theorems he had not proved.", g="1 mark for: he had no university education / was an unknown clerk. 1 mark for: Hardy was a well-known Cambridge mathematician / he sent unproved theorems. Max 2."),
 dict(d="2b", k="tf", m=1, q="Tick True or False for each sentence.", items=["Ramanujan studied at a university before he wrote to Hardy.", "Hardy looked at the list of theorems with J. E. Littlewood.", "Hardy thought that all the results were new and important.", "Ramanujan sailed from India in 1914."], a=["F", "T", "F", "T"], g=TF),
 dict(d="2c", k="order", m=1, q="Number the events from 1 to 4 to show the order in which they happened.", items=["Ramanujan sailed from India.", "Ramanujan was confirmed as a Fellow of the Royal Society.", "Ramanujan wrote a letter to Hardy.", "Hardy replied to Ramanujan\u2019s letter."], a=[3, 4, 1, 2], g=Q2),
 dict(d="2d", k="short", m=1, q="What made Hardy decide to arrange for Ramanujan to travel to England?", a="Some of the results were new and important, and Hardy could see that Ramanujan had a remarkable gift.", g="Accept any answer that refers to the importance or originality of the results, or Ramanujan\u2019s remarkable gift."),
 dict(d="2a", k="mc", m=1, q="In the final paragraph, what does the word \u201cyield\u201d mean in the phrase \u201cstill yield ideas today\u201d?", opts=["Conceal", "Surrender", "Provide", "Repeat"], a="C"),
 dict(d="2g", k="short", m=1, q="The writer says that Carr\u2019s book \u201cwas not a gentle textbook for beginners\u201d. What does this suggest about the book?", a="That it was difficult or demanding to read.", g="Accept: it was hard / challenging / not easy to follow / meant for people who already knew some mathematics."),
 dict(d="2d", k="mc", m=1, q="What does the final paragraph suggest about Ramanujan\u2019s notebooks?", opts=["They are still useful to mathematicians.", "They are now kept in Cambridge.", "They contain mistakes that were corrected.", "They were written for schoolchildren."], a="A"),
 dict(d="2b", k="short", m=1, q="How old was Ramanujan when he was confirmed as a Fellow of the Royal Society?", a="31.", g="Accept 31 or thirty-one."),
 dict(d="2d", k="short", m=1, q="What does the story about the taxi number 1729 suggest about the way Ramanujan thought about numbers?", a="He saw interesting patterns or properties in numbers that other people did not notice, and he knew them very well.", g="Accept any answer that shows he noticed patterns or special facts about numbers quickly / had a deep knowledge of numbers."),
 dict(d="2c", k="mc", m=1, q="Which sentence best sums up paragraphs 3 and 4?", opts=["Ramanujan found a steady job as a clerk and decided to give up mathematics altogether.", "Hardy asked Ramanujan to write a long book explaining theorems for beginners.", "Hardy and Littlewood built a school in Madras to teach mathematics to children.", "Ramanujan wrote to a Cambridge mathematician, who recognised the value of his work."], a="D"),
 dict(d="2b", k="short", m=2, q="Give two honours that Ramanujan received in 1918.", a="He was confirmed as a Fellow of the Royal Society; he was elected a Fellow of Trinity College.", g="1 mark each. Accept Fellow of the Royal Society / Fellow of Trinity College. Max 2."),
])

T(34, "34-7", "Planting an Idea", "Exposition", [
"When a landscape loses its trees, the effects reach further than most people expect, and few have demonstrated this more convincingly than Wangari Maathai. Her work makes a persuasive case that one of the most effective ways of repairing a damaged place is also among the simplest: to plant trees, and to trust ordinary people to plant them.",
"Maathai was born on the 1st of April 1940 near Nyeri, in Kenya. She studied biology at Mount St. Scholastica College in Kansas in the United States, then gained a master\u2019s degree from the University of Pittsburgh. In 1971 she earned a doctorate from the University of Nairobi, becoming the first woman in East and Central Africa to do so.",
"Back in Kenya, Maathai noticed that the land was changing: forests had been cleared, soil was being washed away, streams were drying up and firewood was becoming harder to find, while food supplies were growing less reliable. Her response was practical rather than dramatic, and in 1977 she founded the Green Belt Movement, which encouraged women to grow seedlings of native trees and plant them in their own communities.",
"The argument for this approach rests on what trees actually do. Their roots hold soil in place, so that rain is less likely to carry it away; they provide firewood and food; and they help to protect the water on which people depend. A tree is therefore not a decoration but a working part of the land, and planting one meets several needs at once.",
"Equally important was the way in which the trees were planted. The women who took part were given modest payment, and many were trained in skills such as forestry, food processing and bee-keeping, which helped them to earn a living. This mattered because a tree that is cared for by the person who depends on it is far more likely to survive than one planted and forgotten. Over 30,000 women have been trained in this way.",
"Some people might say that a few seedlings can never make a difference to a whole country. The results suggest otherwise. What began with a small nursery grew into a movement that has planted more than 51 million trees since 1977. Progress on that scale was built one seedling at a time, by people who each did a small job well.",
"In 2004, Maathai was awarded the Nobel Peace Prize, and she was the first African woman to receive it. She was also the first environmentalist to be honoured in this way. The prize recognised that caring for the land is linked with fairness, cooperation and peace.",
"The lesson is plain. Large problems do not always need large machines or large budgets; sometimes they need a good idea, a supply of seedlings and people who are trusted to get on with the work.",
], [
 dict(d="2b", k="short", m=1, q="On what date was Wangari Maathai born?", a="The 1st of April 1940.", g="Accept 1st April 1940 / 1/4/1940 / 1.4.40. Both day and year are needed."),
 dict(d="2a", k="mc", m=1, q="In paragraph 1, what does the word \u201cpersuasive\u201d mean in the phrase \u201ca persuasive case\u201d?", opts=["Long and detailed", "Able to convince", "Hard to understand", "Full of new facts"], a="B"),
 dict(d="2b", k="find", m=1, q="Find and copy the words from paragraph 2 that tell you what Maathai was the first woman to do.", a="the first woman in East and Central Africa", g="Accept \u201cthe first woman in East and Central Africa to do so\u201d. The answer must include East and Central Africa."),
 dict(d="2b", k="short", m=2, q="Give two problems that Maathai noticed when she came back to Kenya.", a="Any two of: forests had been cleared; soil was being washed away; streams were drying up; firewood was harder to find; food supplies were less reliable.", g="1 mark each for two of the problems listed. Max 2."),
 dict(d="2d", k="short", m=2, q="In paragraph 4, the writer says a tree is \u201cnot a decoration but a working part of the land\u201d. Explain what the writer means.", a="A tree does useful jobs, such as holding the soil, giving firewood and food and protecting water, so it is more than something to look at.", g="1 mark for the idea that trees do useful jobs / are not just for looks. 1 mark for a supporting example from the paragraph. Max 2."),
 dict(d="2d", k="short", m=1, q="Why does the writer say that a tree is \u201cfar more likely to survive\u201d if it is cared for by the person who depends on it?", a="That person has a good reason to look after it, because they need what it gives.", g="Accept: they need it, so they will look after it / it matters to them. Do not accept an answer that only repeats \u201cit is cared for\u201d."),
 dict(d="2g", k="short", m=1, q="The writer says progress on this scale \u201cwas built one seedling at a time\u201d. What idea is the writer stressing?", a="That large results can come from many small actions.", g="Accept any answer about big achievements being made up of lots of small steps or efforts."),
 dict(d="2c", k="order", m=1, q="Number the events from 1 to 4 to show the order in which they happened.", items=["Maathai founded the Green Belt Movement.", "Maathai received the Nobel Peace Prize.", "Maathai earned a doctorate from the University of Nairobi.", "Maathai studied biology in the United States."], a=[3, 4, 2, 1], g=Q2),
 dict(d="2b", k="tf", m=1, q="Tick True or False for each sentence.", items=["The Green Belt Movement began in 1977.", "The women who took part were not paid anything.", "Maathai was the first African woman to receive the Nobel Peace Prize.", "Maathai earned her doctorate in the United States."], a=["T", "F", "T", "F"], g=TF),
 dict(d="2d", k="mc", m=1, q="What is the main purpose of paragraph 6?", opts=["To describe how Maathai grew up as a child in Kenya", "To list all of the prizes that she was given", "To answer a doubt that some people might have", "To explain how seedlings are grown in a nursery"], a="C"),
 dict(d="2a", k="mc", m=1, q="In paragraph 5, what does the word \u201cmodest\u201d mean in the phrase \u201cmodest payment\u201d?", opts=["Very large", "Unfair", "Regular", "Small"], a="D"),
 dict(d="2e", k="short", m=1, q="A visitor says, \u201cOne person planting a few trees cannot change anything.\u201d Using the text, how do you think Maathai would answer?", a="She would say that small actions add up: her small nursery grew into a movement that planted millions of trees.", g="Accept any answer that shows small efforts can lead to big results, ideally with reference to the 51 million trees."),
 dict(d="2c", k="mc", m=1, q="Which sentence best sums up the writer\u2019s argument?", opts=["Simple actions by trusted ordinary people can repair damaged land.", "Trees are the only way of protecting a country from every kind of harm.", "Prizes are the best possible reward for people who work very hard.", "Only trained scientists are able to solve environmental problems."], a="A"),
 dict(d="2g", k="short", m=2, q="The writer begins with a general statement about what happens when a landscape loses its trees before mentioning Maathai. Why might the writer have chosen to begin this way?", a="It introduces the problem that Maathai worked on and draws the reader in, so that her solution seems important.", g="1 mark for: introduces the problem / topic or makes the reader curious. 1 mark for a linked explanation (leads to Maathai\u2019s solution / shows why her work mattered). Max 2."),
])

T(34, "34-8", "Learning the Law", "Recount (Historical)", [
"Nelson Mandela was born on the 18th of July 1918 in the village of Mvezo, in the Eastern Cape region of South Africa. At his primary school in Qunu, his teacher gave him the English name Nelson, in accordance with the custom of giving all schoolchildren an English name in those days. It was a small event, yet it marked the start of a long journey through education that would eventually lead him into the law.",
"After primary school he continued his studies at Clarkebury Boarding Institute and then at Healdtown, a secondary school, before going on to the University of Fort Hare. He completed a Bachelor of Arts degree through the University of South Africa in 1943, studying by correspondence, which meant that lessons and assignments travelled by post. Then he began to study law at the University of the Witwatersrand in Johannesburg.",
"Mandela was determined to use his training to help others. At that time, the law in South Africa treated people unfairly according to the colour of their skin, and many people who needed a lawyer found it hard to be heard. In August 1952, Mandela and his friend Oliver Tambo opened a law firm in Johannesburg. It was the first firm in the country to be run by Black partners, and it began in just two small rooms in a building called Chancellor House, in an area of Johannesburg named Ferreirasdorp. The building was later restored and reopened in 2011 as a museum and archive.",
"Word spread quickly, and the office was soon crowded with clients who were seeking help with unfair treatment. Tambo dealt with most of the paperwork, while Mandela spoke on behalf of clients in the magistrates\u2019 courts. Their work showed how the skills of a lawyer, such as careful reading, clear speaking and patience, could be used to give people a voice.",
"Mandela later spent 27 years in prison, and he was released on the 11th of February 1990.",
"After his release, he took part in talks about how South Africa should be governed, and in 1993 he shared the Nobel Peace Prize with F. W. de Klerk. In April 1994 the country held its first election in which people of all races could take part. Mandela\u2019s party won, and on the 10th of May 1994, at the Union Buildings in Pretoria, where thousands of people had gathered, he was inaugurated as president. He became the first Black president of South Africa.",
"As president, Mandela served until 1999, and he declined to stand for a second term. His story shows how a boy who was given a new name at school, and who studied patiently by post, went on to hold the highest office in his country and to receive more than 250 honours.",
], [
 dict(d="2b", k="short", m=1, q="Who gave Nelson Mandela the English name Nelson?", a="His teacher.", g="Accept: his teacher at primary school (in Qunu)."),
 dict(d="2a", k="mc", m=1, q="In paragraph 1, what does the word \u201ccustom\u201d mean in the phrase \u201cin accordance with the custom\u201d?", opts=["A new rule", "A usual habit", "A private wish", "A special prize"], a="B"),
 dict(d="2b", k="find", m=1, q="Find and copy the words from paragraph 2 that tell you how Mandela completed his Bachelor of Arts degree.", a="studying by correspondence", g="Accept \u201cby correspondence\u201d or \u201cstudying by correspondence\u201d."),
 dict(d="2d", k="short", m=1, q="In paragraph 1, the writer says receiving a new name was \u201cthe start of a long journey\u201d. What does the writer mean by \u201cjourney\u201d here?", a="His long progress through education and towards becoming a lawyer.", g="Accept any answer about his education, learning or path towards a career in law. Do not accept a travel journey."),
 dict(d="2c", k="order", m=1, q="Number the events from 1 to 4 to show the order in which they happened.", items=["Mandela opened a law firm with Oliver Tambo.", "Mandela completed a degree through the University of South Africa.", "Mandela became president of South Africa.", "Mandela was given the name Nelson at school."], a=[3, 2, 4, 1], g=Q2),
 dict(d="2d", k="short", m=2, q="Why was the firm that Mandela and Tambo opened important? Use evidence from paragraph 3.", a="It was the first law firm in the country run by Black partners, and it helped people who were treated unfairly to be heard.", g="1 mark for: first law firm run by Black partners. 1 mark for: helped people who had been treated unfairly / needed a lawyer. Max 2."),
 dict(d="2b", k="tf", m=1, q="Tick True or False for each sentence.", items=["Mandela studied law at the University of the Witwatersrand.", "Mandela dealt with most of the paperwork at the law firm.", "The law firm opened in 1952.", "Mandela became president in 1990."], a=["T", "F", "T", "F"], g=TF),
 dict(d="2b", k="short", m=1, q="On what date was Mandela inaugurated as president?", a="The 10th of May 1994.", g="Accept 10th May 1994 / 10/5/1994. Day, month and year are needed."),
 dict(d="2a", k="mc", m=1, q="In paragraph 6, what does \u201cinaugurated\u201d mean?", opts=["Officially made leader", "Chosen by a neighbour", "Sent to another country", "Asked to give a speech"], a="A"),
 dict(d="2g", k="short", m=1, q="In paragraph 4, the writer says the skills of a lawyer could be used \u201cto give people a voice\u201d. What does this mean?", a="To help people to be heard / to speak up for people who were not being listened to.", g="Accept any answer about helping people to be heard, listened to or represented."),
 dict(d="2d", k="mc", m=1, q="Why was the office \u201csoon crowded with clients\u201d?", opts=["The firm had opened in a very small building.", "Mandela had recently become very famous across the country.", "Many people wanted help with unfair treatment.", "The law had recently changed so more people needed lawyers."], a="C"),
 dict(d="2d", k="short", m=1, q="What does the writer suggest about Mandela\u2019s character when describing how he completed his degree?", a="That he was patient, determined and hard-working.", g="Accept any of: determined, patient, hard-working, dedicated, committed."),
 dict(d="2c", k="mc", m=1, q="Which sentence best sums up the whole text?", opts=["Mandela worked as a teacher in Qunu for many years before moving to Pretoria.", "Mandela studied hard, worked as a lawyer and became president in 1994.", "Mandela wrote several books about the law while he lived in Johannesburg.", "Mandela won an election and then retired from law to become a farmer."], a="B"),
 dict(d="2g", k="short", m=2, q="The last paragraph mentions again \u201ca boy who was given a new name at school\u201d. Why do you think the writer finishes by referring back to the beginning?", a="It shows how far Mandela travelled from his small beginnings to the highest office, and it gives the text a neat, complete ending.", g="1 mark for: shows the contrast between the beginning and the end / how far he went. 1 mark for: links the ending to the start / finishes the story neatly. Max 2."),
])

